{
  "findings": [
    {
      "check_id": "AVD-AWS-0067",
      "title": "Lambda permission lacks source ARN for *.amazonaws.com principal",
      "resource": "aws_lambda_permission.api_gateway_invoke",
      "severity": "CRITICAL",
      "explanation": "The Lambda permission does not specify a source ARN, which allows any API Gateway in any AWS account to invoke the Lambda function. This can lead to unauthorized access."
    }
  ],
  "patched_code": "resource \"aws_lambda_permission\" \"api_gateway_invoke\" {\n  statement_id  = \"AllowExecutionFromAPIGateway\"\n  action        = \"lambda:InvokeFunction\"\n  function_name = aws_lambda_function.log_processing_pipeline.function_name\n  principal     = \"apigateway.amazonaws.com\"\n  source_arn    = \"arn:aws:execute-api:${var.region}:${var.account_id}:${var.api_id}/*\"\n}",
  "fix_summary": "Added a 'source_arn' attribute to the Lambda permission to restrict invocation to a specific API Gateway in the same account and region."
}
